files.content:
:root {
  --bg: #1a1423;
  --card: #2e2438;
  --accent: #ffd166;
  --accent-dark: #e6a817;
  --text: #f5f0ff;
  --muted: #b8a9c9;
  --border: #4a3a5c;
  --shadow: #0d0a12;
  --font: "Courier New", Courier, monospace;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  min-height: 100%;
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  background-color: var(--bg);
  background-image:
    linear-gradient(rgba(255, 209, 102, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 209, 102, 0.06) 1px, transparent 1px);
  background-size: 16px 16px;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 24px 20px 28px;
}

h1 {
  margin: 0 0 20px;
  font-size: 1.6rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 3px 3px 0 var(--shadow);
  text-align: center;
}

.field {
  margin: 0 0 18px;
  padding: 0;
  border: 0;
}

label, legend {
  display: block;
  margin-bottom: 8px;
  font-size: 1rem;
  font-weight: bold;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--muted);
}

input[type="number"] {
  width: 100%;
  padding: 12px 14px;
  font-family: var(--font);
  font-size: 1.25rem;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--border);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

input[type="number"]::placeholder {
  color: var(--muted);
  opacity: 0.6;
}

input[type="number"]:hover {
  border-color: var(--accent-dark);
}

input[type="number"]:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.35);
}

.tip-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.tip-btn {
  padding: 14px 8px;
  font-family: var(--font);
  font-size: 1.1rem;
  font-weight: bold;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--border);
  cursor: pointer;
  transition: transform 0.1s ease, background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.tip-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.tip-btn:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.35);
}

.tip-btn:active {
  transform: translate(2px, 2px);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent-dark);
  color: var(--bg);
  box-shadow: 3px 3px 0 var(--shadow);
}

.tip-btn[aria-pressed="true"]:hover {
  color: var(--bg);
  background: #ffdd8a;
}

.results {
  margin-top: 24px;
  padding: 16px;
  background: var(--bg);
  border: 3px dashed var(--border);
}

.result-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 6px 0;
}

.result-row + .result-row {
  border-top: 2px dotted var(--border);
  margin-top: 6px;
  padding-top: 12px;
}

.result-label {
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}

.result-value {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--shadow);
}

@media (max-width: 380px) {
  .card {
    padding: 20px 14px 24px;
  }

  h1 {
    font-size: 1.35rem;
  }

  .tip-btn {
    font-size: 1rem;
    padding: 12px 4px;
  }

  .result-value {
    font-size: 1.3rem;
  }
}

(function () {
  "use strict";

  var billInput = document.getElementById("bill");
  var peopleInput = document.getElementById("people");
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll(".tip-btn"));
  var tipDisplay = document.getElementById("tip");
  var totalDisplay = document.getElementById("total");

  var tipPercent = 0;

  function formatMoney(value) {
    if (!isFinite(value) || value < 0) {
      value = 0;
    }
    return "$" + value.toFixed(2);
  }

  function calculate() {
    var bill = parseFloat(billInput.value);
    var people = parseInt(peopleInput.value, 10);

    if (!isFinite(bill) || bill < 0) {
      bill = 0;
    }
    if (!isFinite(people) || people < 1) {
      people = 1;
    }

    var tipAmount = bill * (tipPercent / 100);
    var totalPerPerson = (bill + tipAmount) / people;

    tipDisplay.textContent = formatMoney(tipAmount);
    totalDisplay.textContent = formatMoney(totalPerPerson);
  }

  function selectTip(button) {
    tipButtons.forEach(function (btn) {
      var isSelected = btn === button;
      btn.setAttribute("aria-pressed", isSelected ? "true" : "false");
    });
    tipPercent = parseFloat(button.getAttribute("data-tip")) || 0;
    calculate();
  }

  tipButtons.forEach(function (button) {
    button.addEventListener("click", function () {
      selectTip(button);
    });
  });

  billInput.addEventListener("input", calculate);
  peopleInput.addEventListener("input", calculate);

  calculate();
})();
